"""A readable project story with an optional scroll-driven CSS 3D scene."""
def story(base, icon):
    chapters=[
        ('discover','Discover','Start with the work.','Tell us what needs to improve: a workflow, an application, connected systems or the equipment your team relies on.','Your goals · Your users · Your priorities'),
        ('design','Design','Give the idea a clear shape.','Explore the requirements, suitable technology and how the parts should work together. Agree the scope before moving forward.','Requirements · Architecture · Agreed scope'),
        ('connect','Build & connect','Bring the right pieces together.','Discuss software, AI agents, automation, cloud integration or hardware supply around the agreed project requirements.','Software & AI · Connected systems · Equipment'),
        ('support','Launch & support','Plan for what comes next.','Define implementation, installation, maintenance and support arrangements for the solution you choose.','Implementation · Installation · Ongoing support'),
    ]
    links=''.join(f'<a href="#story-{key}" data-story-link="{i}"'+(' aria-current="step"' if i==0 else '')+f'><span>{i+1:02}</span>{label}</a>' for i,(key,label,*_) in enumerate(chapters))
    steps=''.join(f'<article class="cinema-chapter" id="story-{key}" data-story-step="{i}"><span class="mini-label">{i+1:02} / {label.upper()}</span><h3>{title}</h3><p>{copy}</p><span class="cinema-chapter-tags">{tags}</span></article>' for i,(key,label,title,copy,tags) in enumerate(chapters))
    modules=''.join(f'<div class="cinema-module cinema-module-{i}">{icon(kind)}</div>' for i,kind in enumerate(['consulting','network','hardware','support']))
    return f'''<section class="cinema-story" data-cinema-story aria-labelledby="cinema-title">
    <div class="wrap"><div class="section-head"><div><div class="eyebrow">FROM THE FIRST QUESTION TO WHAT COMES NEXT</div><h2 id="cinema-title">Watch the pieces<br>come together.</h2></div><p>Every project starts with your business. Explore how we move from a requirement to a connected technology plan.</p></div>
    <div class="cinema-layout"><div class="cinema-sticky"><div class="cinema-stage" aria-hidden="true"><div class="cinema-stage-grid"></div><div class="cinema-assembly"><div class="cinema-ring"></div><div class="cinema-deck"></div><svg class="cinema-connections" viewBox="0 0 360 360" fill="none"><path d="M65 65 180 180 295 65M65 295 180 180 295 295"/></svg><div class="cinema-core"><img src="{base}assets/mark.svg" width="90" height="90" alt=""></div>{modules}</div><div class="cinema-caption"><span data-story-number>01 / 04</span><b data-story-caption>Discover</b><div class="cinema-meter"><i></i></div></div></div>
    <nav class="cinema-chapter-nav" aria-label="Explore the project story">{links}</nav><button class="cinema-pause" type="button" data-cinema-pause aria-pressed="false" hidden>Pause scene motion</button></div><div class="cinema-chapters">{steps}<a class="text-link" href="{base}request-quote/">Tell us about your project ↗</a></div></div></div></section>'''
